const fs = require('node:fs');
const crypto = require('node:crypto');
const V = (m) => { console.error('PPE_PROVEN_DOC_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('PPE_PROVEN_DOC_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const p = "docs/architecture/audits/PATTERN-PROOF-ENGINE-01-V1-BOOTSTRAP-RED-ONLY-PROVEN.md";
  const o = "docs/architecture/audits/PATTERN-PROOF-ENGINE-01-V1-BOOTSTRAP-RED-ONLY.md";
  let s;
  try { s = fs.readFileSync(p, 'utf8'); }
  catch (e) { if (e && e.code === 'ENOENT') V('the PROVEN record does not exist on this tree: ' + p); H('cannot read ' + p + ': ' + (e && e.message)); }
  const req = JSON.parse(process.argv[1]);
  if (!Array.isArray(req) || req.length === 0) H('no required bindings supplied');
  const missing = req.filter((x) => !s.includes(x));
  if (missing.length > 0) V('the PROVEN record lacks required bindings: ' + missing.join(' | '));
  const grab = (label) => { const m = new RegExp('\\*\\*' + label + ':\\*\\* `([0-9a-f]{40})`').exec(s); return m && m[1]; };
  const mt = grab('Merge tree'), ct = grab('Candidate tree');
  if (!mt || !ct) V('merge tree / candidate tree are not both stated as 40-hex SHAs');
  if (mt !== ct) V('merge tree ' + mt + ' differs from candidate tree ' + ct + ': finalization is blocked');
  let ob;
  try { ob = fs.readFileSync(o); }
  catch (e) { H('cannot read ' + o + ': ' + (e && e.message)); }
  const keep = 75666;
  const want = "875600635cc1921f0ec470a844460bdcf98c1cb735b2e98f916fc387d4c2320e";
  if (ob.length <= keep) V('the candidate record was not extended (' + ob.length + ' bytes, base has ' + keep + ')');
  const got = crypto.createHash('sha256').update(ob.subarray(0, keep)).digest('hex');
  if (got !== want) V('the candidate record\'s existing text changed: prefix sha256 ' + got + ' != ' + want);
  const tail = ob.subarray(keep).toString('utf8');
  if (!tail.includes("1e9d523fd551b940651e835f3194d412dd60409e")) V('the appended section does not name the refreshed base anchor');
  if (/\*\*Final state:\*\*\s*PROVEN/.test(ob.toString('utf8'))) V('the candidate record must not carry a PROVEN final state; that is this separate record');
  console.log('PPE_PROVEN_DOC_OK: record binds all required evidence; merge tree == candidate tree ' + mt + '; candidate record kept its ' + keep + ' bytes and gained ' + (ob.length - keep));
} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

